import { readFile, writeFile } from 'node:fs/promises';

const root = new URL('../', import.meta.url);
const catalog = JSON.parse(await readFile(new URL('src/report-catalog.json', root), 'utf8'));
const page = new URL('docs-site/content/docs/reports.mdx', root);
const lines = [
  '---', 'title: Command reference',
  `description: All ${Object.keys(catalog).length} research and account operations, with schema-derived options.`,
  '---', '', '{/* Generated by npm run docs:generate from src/report-catalog.json. */}', '',
  'Every command also has an MCP tool with underscores in its name. Use `--json` for scripts.', '',
];
for (const [name, definition] of Object.entries(catalog)) {
  const command = name.replaceAll('_', '-');
  lines.push(`## ${command}`, '', definition.description, '', '```sh', `semrush ${command} --help`, '```', '');
  if (definition.mutation) lines.push('Requires `--confirm`. Use `--dry-run` to inspect the request without sending it.', '');
  if (definition.response_type === 'download') lines.push('CLI requires `--output <path>` and refuses existing files. MCP returns an export artifact URI readable through `resources/read`.', '');
  const properties = Object.entries(definition.schema.properties);
  if (!properties.length) continue;
  lines.push('| Flag | Type | Default | Required |', '| --- | --- | --- | --- |');
  for (const [key, property] of properties) {
    const type = property.type ?? property.anyOf?.map(candidate => candidate.type).join(' / ') ?? '';
    const fileInput = property.writeOnly === true || Boolean(property.contentMediaType);
    const defaultValue = property.default === undefined ? '' : '`' + JSON.stringify(property.default).replaceAll('|', '\\|') + '`';
    const required = definition.schema.required?.includes(key) ? 'yes' : '';
    lines.push(`| \`--${key.replaceAll('_', '-')}${fileInput ? '-file' : ''}\` | ${fileInput ? 'file path or - for stdin' : type} | ${defaultValue} | ${required} |`);
  }
  lines.push('');
}
const generatedFiles = new Map([
  [page, lines.join('\n') + '\n'],
  [new URL('docs-site/lib/operation-count.ts', root), '// Generated by npm run docs:generate from src/report-catalog.json.\nexport const operationCount = ' + Object.keys(catalog).length + ';\n'],
]);
for (const [path, generated] of generatedFiles) {
  if (process.argv.includes('--check')) {
    if (await readFile(path, 'utf8') !== generated) {
      process.stderr.write('Command documentation is stale. Run npm run docs:generate.\n');
      process.exitCode = 1;
    }
  } else await writeFile(path, generated);
}
